import{_ as d,o as r,c as a,ai as s}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"02 工业数字化应用","description":"","frontmatter":{},"headers":[],"relativePath":"instances/industrial/index.md","filePath":"instances/industrial/index.md"}'),n={name:"instances/industrial/index.md"};function e(o,t,i,l,h,p){return r(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="_02-工业数字化应用" tabindex="-1">02 工业数字化应用 <a class="header-anchor" href="#_02-工业数字化应用" aria-label="Permalink to “02 工业数字化应用”">​</a></h1><blockquote><p><strong>MES</strong> 生产执行 · <strong>IIoT</strong> 工业物联网 · <strong>WMS</strong> 仓储 —— 现场三层，共用 OpenBiz 底座。</p></blockquote><p><strong>状态图例</strong>：✅ 已验证 · 🔧 在建 · 📋 规划中</p><h2 id="初衷-为什么是工业-为什么是三个" tabindex="-1">初衷：为什么是工业，为什么是三个 <a class="header-anchor" href="#初衷-为什么是工业-为什么是三个" aria-label="Permalink to “初衷：为什么是工业，为什么是三个”">​</a></h2><p><strong>一句话：我做过这些，但带不走，所以重做一遍。</strong></p><p>十年里跟工业真正沾边的是两段：钢瓶企业的轻量 MES（五端协同、设备采集，现场交付与联调），和更早的 IoT 项目。这两段是我简历里最有分量的业务经历，偏偏也是最难证明的——代码在客户机房，文档留在公司，面试时只能靠嘴说。</p><p>「我做过 MES」这句话，对方听完只能选择信或不信。我不想让人靠「信」。</p><p>所以做了个决定：<strong>把做过的东西，用能公开的方式重做一遍</strong>。同一类业务、同样的现场约束，换成自己的代码、自己的库表、自己能跑起来的 E2E。工单的七个状态、库存的三个数、设备断线后的补传，都不是为了凑项目数量——是现场真实卡过我的问题。</p><p><strong>为什么是工业，不是电商或后台管理。</strong> 因为工业系统的难点不在技术栈，在业务规则：工单状态能不能乱、库存怎么才算对得上、设备断十分钟数据怎么补。规则写错，系统就没人敢用。能把这类规则讲清楚、写对，比多写几个 CRUD 更能说明问题——而工业恰好是我真有经验的地方。</p><p><strong>为什么三个一起做。</strong> 工厂里设备、工单、库存是三段咬合的业务。只做一个 MES，讲出来是一张功能清单；三个一起，才讲得清边界在哪、协同怎么发生——IIoT 只管采集，MES 只管执行，WMS 只管账。而「谁都想要别人的数据」，恰恰是真实项目里最容易出事的地方。</p><p><strong>为什么共用一套底座。</strong> 我做过四年 CRM / ERP / OA 的定制交付，习惯的工作方式就是「一套底座 + 多客户定制」。用 OpenBiz 的 <code>saas-core</code> 承载这三个系统，等于顺手验证一件事：这套底座能不能复制到第四个、第五个域。</p><p><strong>最后把边界说清楚。</strong> 这三个是可复现的重建版本，不是公司项目的原件。规模、并发、客户现场的复杂度都不等同于真实交付；页面里每个「已实现 / 待做」都按实际状态标，没做完的不会写成做完了。把边界写明白，比把 Demo 吹成产品更可信——这也是我对自己交付习惯的要求。</p><h2 id="业务全景" tabindex="-1">业务全景 <a class="header-anchor" href="#业务全景" aria-label="Permalink to “业务全景”">​</a></h2><p>这三个系统不是三个并列的 Demo，而是同一家工厂里同时发生、彼此咬合的三段业务：<strong>设备在转、单在产、料在动</strong>。客户一张订单进来，会在三个系统之间走一圈：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>客户订单 → 生产计划 → 领料出库 WMS → 工单执行 MES → 质检放行 MES → 完工入库 WMS → 发货 WMS</span></span>
<span class="line"><span>                                          ↑</span></span>
<span class="line"><span>                            设备状态 / 产量 / 告警（IIoT 持续供数）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>每个系统只回答一个业务问题，回答不了的交出去：</p><table tabindex="0"><thead><tr><th>系统</th><th>回答的问题</th><th>不管什么</th></tr></thead><tbody><tr><td><strong>IIoT</strong></td><td>这台设备现在什么状态？这个参数刚才多少？</td><td>不碰工单，不碰库存</td></tr><tr><td><strong>MES</strong></td><td>这批货做到哪一步了？谁在做？合格没有？</td><td>不碰设备协议，不碰库位</td></tr><tr><td><strong>WMS</strong></td><td>料和货在哪、还有多少、先出哪一批？</td><td>不碰工序，不碰工单进度</td></tr></tbody></table><p>对应到人——工厂里六个角色，各看各的屏：</p><table tabindex="0"><thead><tr><th>角色</th><th>主要落在</th><th>关心的事</th></tr></thead><tbody><tr><td>计划员</td><td>MES</td><td>交期能不能赶上，哪张单卡住了</td></tr><tr><td>班组长</td><td>MES · IIoT 看板</td><td>今天要做几张单，设备有没有异常</td></tr><tr><td>操作工</td><td>MES 报工</td><td>这单做完了，报多少、合格多少</td></tr><tr><td>质检员</td><td>MES 质检 · WMS 到货检</td><td>这批能不能放行</td></tr><tr><td>仓管</td><td>WMS</td><td>账实对不对，先到期的是哪批</td></tr><tr><td>设备工程师</td><td>IIoT</td><td>哪台设备在报警，历史曲线长什么样</td></tr></tbody></table><p>一句话概括这套东西：<strong>把一家工厂的三本账——设备账、生产账、库存账——做成能跑的系统</strong>。三本账各记各的，但一张订单穿过三本账时，数量和时间必须对得上。</p><h2 id="这些系统为什么存在" tabindex="-1">这些系统为什么存在 <a class="header-anchor" href="#这些系统为什么存在" aria-label="Permalink to “这些系统为什么存在”">​</a></h2><p>工业软件不是把纸单子搬到屏幕上。它接手的是人本来就做不好的三件事：<strong>记不住、算不准、跟不上</strong>。</p><table tabindex="0"><thead><tr><th>人做不到的</th><th>现场长什么样</th><th>系统要接手的</th></tr></thead><tbody><tr><td><strong>记不住</strong></td><td>一个月后追一批货用了哪批料、谁经手的，只能靠回忆和对质</td><td>全链路留痕：谁、何时、哪台设备、哪批料、做了什么</td></tr><tr><td><strong>算不准</strong></td><td>账面一千、实际八百，月底盘亏查不出是谁弄错的</td><td>每笔变动有流水兜底，库存三个数必须恒等</td></tr><tr><td><strong>跟不上</strong></td><td>设备停了两个小时没人知道，等交期废了才发现</td><td>状态实时可见，异常自动冒头，不用等人巡检</td></tr></tbody></table><h3 id="四层问题-层次决定它值多少钱" tabindex="-1">四层问题，层次决定它值多少钱 <a class="header-anchor" href="#四层问题-层次决定它值多少钱" aria-label="Permalink to “四层问题，层次决定它值多少钱”">​</a></h3><p>工业软件解决的问题是分层的。停在哪一层，决定了它是个更贵的 Excel，还是真管理系统：</p><table tabindex="0"><thead><tr><th>层次</th><th>解决的问题</th><th>典型能力</th><th>只做到这层的后果</th></tr></thead><tbody><tr><td><strong>1 记录</strong></td><td>事实留痕，事后查得到</td><td>报工记录、出入库流水、设备历史数据</td><td>电子台账，比 Excel 好看一点</td></tr><tr><td><strong>2 约束</strong></td><td>规则不许绕过</td><td>工单状态机、库存不能为负、无质检不放行</td><td>有了规则，数据才有人敢信</td></tr><tr><td><strong>3 协同</strong></td><td>跨角色、跨系统对账</td><td>一张订单穿过三本账，数量和时间对得上</td><td>部门之间不再互相甩锅</td></tr><tr><td><strong>4 判断</strong></td><td>数据变成决策依据</td><td>交期预测、瓶颈识别、良率趋势</td><td>从记录系统升级成管理系统</td></tr></tbody></table><p><strong>大部分工业软件死在第 1 层</strong>：功能清单很长，但每条规则都能被人为绕过，数据没人敢拿来做决定，最后就变成一个更贵、更难用的 Excel。这也是为什么下面三个系统我都要写状态机和流水——不是为了技术好看，是让规则<strong>绕不过去</strong>。</p><h3 id="三个系统各守一道门" tabindex="-1">三个系统各守一道门 <a class="header-anchor" href="#三个系统各守一道门" aria-label="Permalink to “三个系统各守一道门”">​</a></h3><table tabindex="0"><thead><tr><th>系统</th><th>没有它的时候</th><th>它守的规则</th></tr></thead><tbody><tr><td><strong>MES</strong></td><td>计划下发之后就是黑箱：做到哪一步、谁在做、合不合格，全靠走到车间问</td><td>工单状态不许跳；没有质检不能完工；报工数不能超计划</td></tr><tr><td><strong>WMS</strong></td><td>库存是糊涂账，先进先出靠仓管记忆，发错批次没人察觉</td><td>库存三个数恒等；流水只增不改；发货按批次先进先出</td></tr><tr><td><strong>IIoT</strong></td><td>设备状态靠人巡检，故障靠等，产量靠手抄，抄完还不准</td><td>断线要补传；超阈值必须告警；采集频率按用途分级</td></tr></tbody></table><h3 id="它解决不了什么" tabindex="-1">它解决不了什么 <a class="header-anchor" href="#它解决不了什么" aria-label="Permalink to “它解决不了什么”">​</a></h3><p>把边界写清楚，比把功能吹满有用：</p><ul><li><strong>不解决管理问题</strong>：现场没人愿意报工，系统再好也是一张空表</li><li><strong>不解决数据质量</strong>：物料编码一开始就乱，系统只会把这个乱放大得更快</li><li><strong>不解决人的习惯</strong>：让老师傅在屏幕上多点两下，比加十个功能难得多</li><li><strong>不替代工艺</strong>：系统不会告诉你这道工序该几度、几分钟——那是工艺员的事</li></ul><p><strong>一句话</strong>：工业系统的价值不在功能多少，在<strong>规则是否真的被执行</strong>。五个功能但绕不过去，比五十个功能但随时能被绕过值钱。</p><h2 id="项目一览" tabindex="-1">项目一览 <a class="header-anchor" href="#项目一览" aria-label="Permalink to “项目一览”">​</a></h2><table tabindex="0"><thead><tr><th>序号</th><th>项目</th><th>一句话</th><th>状态</th><th>工程</th></tr></thead><tbody><tr><td>1</td><td><a href="./mes.html">MES 生产执行管理系统</a></td><td>工单七态 · 工序报工 · 质检 · 跨 WMS/IIoT</td><td>✅ P0 已收口</td><td><code>openbiz-mes-app</code> · :18082</td></tr><tr><td>2</td><td><a href="./iiot.html">IIoT 工业物联网监控系统</a></td><td>MQTT/Modbus · 规则告警 · 看板 · P0-15 E2E</td><td>✅ P0 已收口</td><td><code>openbiz-iiot-app</code> · :18089</td></tr><tr><td>3</td><td><a href="./wms.html">WMS 仓储管理系统</a></td><td>三态库存 · 盘点调拨 · CI/Swagger · 单 jar</td><td>✅ 生产化 A/B/C 齐</td><td><code>openbiz-wms-app</code> · :18086</td></tr></tbody></table><h2 id="三系统协同" tabindex="-1">三系统协同 <a class="header-anchor" href="#三系统协同" aria-label="Permalink to “三系统协同”">​</a></h2><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[ IIoT 感知层 ]  设备状态 / 产量 / 告警</span></span>
<span class="line"><span>        │  OpenAPI / MQ</span></span>
<span class="line"><span>[ MES 执行层 ]  工单 / 工序 / 报工 / 质检</span></span>
<span class="line"><span>        │  领料 / 完工入库</span></span>
<span class="line"><span>[ WMS 物流层 ]  库存 / 出入库 / 库位 / 批次</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>[ OpenBiz saas-core ]  多租户 / 权限 / 状态机（共用）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><ul><li>主数据：SKU/BOM 归平台或 ERP；设备归 IIoT；库位归 WMS</li><li>集成：同步 OpenAPI，异步部分已落地（MES↔WMS outbox、MES←IIoT 轮询）；独立库、不共享表</li><li>公司钢瓶 MES（简历）≠ 本仓库 OpenBiz MES（可复现 Demo）</li></ul><h2 id="水平自评-覆盖到哪、面试够不够" tabindex="-1">水平自评：覆盖到哪、面试够不够 <a class="header-anchor" href="#水平自评-覆盖到哪、面试够不够" aria-label="Permalink to “水平自评：覆盖到哪、面试够不够”">​</a></h2><blockquote><p>口径：<strong>「中小离散制造 / 自营仓 / 设备监控」</strong> 这一档客户的日常业务，不是汽车电子万级点位、也不是 3PL 多货主。百分比是「场景是否说得清、规则是否绕不过去」，不是功能清单完成度。</p></blockquote><h3 id="三系统分别到哪一档" tabindex="-1">三系统分别到哪一档 <a class="header-anchor" href="#三系统分别到哪一档" aria-label="Permalink to “三系统分别到哪一档”">​</a></h3><table tabindex="0"><thead><tr><th>系统</th><th>约覆盖</th><th>已经站得住的</th><th>还撑不住的</th></tr></thead><tbody><tr><td><strong>WMS</strong></td><td><strong>~75–85%</strong> 自营仓日常</td><td>收发存主链、三态+流水、FEFO、盘点/调拨/退货、RBAC/审计/备份、报表/PDA 壳、CI·Docker·Swagger</td><td>波次/上架策略、库存冻结、批次全厂追溯 UI、正式 <code>/open/v1</code> 对外契约、万级 SKU</td></tr><tr><td><strong>MES</strong></td><td><strong>~55–65%</strong> 小批量装配执行</td><td>七态工单、工序报工+WIP 不变量、质检明细、单工单追溯、完工→WMS、IIoT 计数报工、CAS 禁删</td><td>工厂/产线主数据、班次、齐套领料、PDA/看板前端、跨工单批次追溯、排产</td></tr><tr><td><strong>IIoT</strong></td><td><strong>~70–75%</strong> 监控演示到可连真设备</td><td>MQTT+Modbus TCP/RTU、S7 SoftPLC、OPC-UA Soft、点位/攒批/缓存/降采样、规则+通知、看板、P0-15 E2E、P1-16 协议环回</td><td>完整 opc.tcp Binary、真 RS485/PLC、边缘离线、TDengine、OEE、万级点位、断库故障注入</td></tr></tbody></table><p><strong>合在一起</strong>：工厂「设备在转、单在产、料在动」的<strong>叙事与约束层</strong>大约到 <strong>60–70%</strong>；若只谈仓储交付，WMS 单独可冲到 <strong>约 80%</strong> 的中小仓场景。跨系统「一张订单穿三本账」的闭环有 MES↔WMS / MES←IIoT 实证，但还不是完整 ERP 级订单编排。</p><p>对应前面的四层模型：三系统都稳在 <strong>第 2 层（约束）</strong>，WMS/MES 部分进入 <strong>第 3 层（协同）</strong>，<strong>第 4 层（判断/预测）基本未做</strong>——面试时这样拆，比说「做了三个大系统」更可信。</p><h3 id="还建议补什么-按面试性价比" tabindex="-1">还建议补什么（按面试性价比） <a class="header-anchor" href="#还建议补什么-按面试性价比" aria-label="Permalink to “还建议补什么（按面试性价比）”">​</a></h3><table tabindex="0"><thead><tr><th>优先级</th><th>补什么</th><th>为什么</th></tr></thead><tbody><tr><td>P0</td><td>面试口述稿：三态库存、工单 CAS、告警迟滞各 90 秒</td><td>对方问的是「你为什么这样设计」，不是功能数</td></tr><tr><td>P0</td><td>本地一键演示路径（WMS <code>verify_all</code> / MES <code>run_mes_e2e</code> / IIoT <code>verify-p0-15</code>）练熟</td><td>能当场打开比 PPT 强</td></tr><tr><td>P1</td><td>WMS <code>/open/v1</code> 领料·完工入库正式端点（设计已有）</td><td>把「跨系统」从 MES 侧单方调用讲成双边契约</td></tr><tr><td>P1</td><td>MES 工序/追溯/集成的前端页（接口已有）</td><td>避免「后端很全、页面只有两张表」被追问</td></tr><tr><td>P1</td><td>IIoT 真设备或录像（一台 Modbus 从站/PLC）</td><td>证明不是只跑内嵌模拟</td></tr><tr><td>P2</td><td>断库补传/队列溢出故障演练、浏览器 E2E</td><td>工程完整度加分，非入门门槛</td></tr><tr><td>不做也行</td><td>APS、SCADA 组态、分库分表、3PL</td><td>范围外；写进「明确不做」比硬做更加分</td></tr></tbody></table><h3 id="面试准备-够不够" tabindex="-1">面试准备：够不够 <a class="header-anchor" href="#面试准备-够不够" aria-label="Permalink to “面试准备：够不够”">​</a></h3><p><strong>够做「有工业背景的后端 / 全栈」基本面试准备</strong>，前提是你能讲清下面几类问题（每条都有代码与断言可指）：</p><ol><li><strong>库存为什么是三个数</strong>（<code>on_hand / reserved / locked</code>），CAS 如何防超卖</li><li><strong>工单状态机非法流转为什么必须 409</strong>，并发开工如何 <code>AND status = from</code></li><li><strong>告警为什么要持续时长 + 迟滞 + 收敛</strong>，和「阈值一过就刷屏」的差别</li><li><strong>跨系统为什么用 outbox</strong>，WMS 挂了车间为什么还能报工</li><li><strong>多租户 / 权限按动作切</strong>，和 CRUD 权限的差别</li></ol><p>不够单独支撑的：<strong>大厂基础架构岗</strong>（中间件内核）、<strong>纯算法/APS</strong>、<strong>现场交钥匙总包</strong>（实施、培训、硬件联调占比极高）。那些要另备项目或经历，不要靠这三个 Demo 硬撑。</p><p>实践沉淀见 <a href="/my-vitepress-site/apps/industrial/">功能开发 › 工业数字化</a>。</p><hr><p>上一级：<a href="/my-vitepress-site/instances/">应用实例</a></p>`,53)])])}const c=d(n,[["render",e]]);export{b as __pageData,c as default};
